def clean(df):
    d = df.copy()
    s = d["body_mass_g"].astype(str).str.strip().str.replace(",", "", regex=False)
    d["body_mass_g"] = pd.to_numeric(s, errors="coerce")
    return d

def answer(df):
    d = clean(df)
    d = d.dropna(subset=["species", "body_mass_g"])
    g = d.groupby("species")["body_mass_g"].sum()
    return {str(k): int(round(float(v))) for k, v in g.items()}
